         body='// CertFactory: builds certificates with Bouncy Castle\nif (spec.authority()) {\n    builder.addExtension(Extension.basicConstraints, true,\n            new BasicConstraints(spec.pathLength()));                  // a CA, and how deep\n    builder.addExtension(Extension.keyUsage, true,\n            new KeyUsage(KeyUsage.keyCertSign | KeyUsage.cRLSign));     // bits 5 and 6\n} else {\n    builder.addExtension(Extension.basicConstraints, true, new BasicConstraints(false));\n    builder.addExtension(Extension.keyUsage, true,\n            new KeyUsage(KeyUsage.digitalSignature));                   // bit 0\n...\nbuilder.addExtension(Extension.nameConstraints, true,\n        new NameConstraints(new GeneralSubtree[] {permitted}, null));',
